540			private int speedupStopwatchID = -1;
541	
542			private NumVarStatMod moveSpeedMod;
543	
544			private float currentMSPercentage;
545	
546			private NumVarStatMod animSpeedMod;
547	
548			private ChaosQuickStopwatch animStopwatch = new ChaosQuickStopwatch(0.25f);
