560			public RunState(string stateName, FSM parentFSM, Player parentEntity)
561				: base(stateName, parentFSM, parentEntity)
562			{
563				moveSpeedMod = new NumVarStatMod(modStrID, 0.4f, 10, VarStatModType.LateMultiplicative);
564				animSpeedMod = new NumVarStatMod(modStrID, 1f, 1, VarStatModType.Override);
565				parryStopwatch = new ChaosQuickStopwatch(parent.parryActiveTime);
566			}
567	
568			public override void OnEnter()
569			{
570				parent.anim.PlayDirectional(name + parent.facingDirection);
571				speedupStopwatchID = ChaosStopwatch.Begin(parent.runSpeedupStat.CurrentValue);
572				moveSpeedApplied = false;
573				dashSkill = parent.GetDashSkill();
574				if (parent.parryAvailStat.CurrentValue)
575				{
576					parent.parryActive = true;
577					parryStopwatch.IsRunning = true;
578				}
579			}
580	
581			public override void FixedUpdate()
582			{
583				if (parent.parryAvailStat.CurrentValue)
584				{
585					if (parent.parryActive)
586					{
587						parent.parryActive = parryStopwatch.IsRunning;
588					}
589					else if (currMoveVec != Vector2.zero && Vector2.Angle(currMoveVec, lastMoveVec) > 100f)
590					{
591						parent.parryActive = true;
592						parryStopwatch.IsRunning = true;
593					}
594				}
595			}
