597			public override void Update()
598			{
599				if (parent.HandleSkills(allowButtonHeld: false, string.Empty))
600				{
601					return;
602				}
603				inputDir = GetInputDirection(parent.inputDevice);
604				if (inputDir == FacingDirection.Neutral)
605				{
606					if (moveSpeedApplied)
607					{
608						parent.movement.dashVector = parent.movement.moveVector;
609						fsm.ChangeState(SlideState.staticID);
610					}
611					else
612					{
613						fsm.ChangeState(fsm.defaultStateName);
614					}
615					return;
616				}
617				if (parent.facingDirection != inputDir)
618				{
619					parent.facingDirection = inputDir;
620					parent.anim.PlayDirectional(name + parent.facingDirection);
621				}
622				parent.movement.MoveOnInput(parent.inputDevice);
623				lastMoveVec = currMoveVec;
624				currMoveVec = parent.movement.moveVector;
625				if (dashSkill != null && !moveSpeedApplied && ChaosStopwatch.Check(speedupStopwatchID))
626				{
627					moveSpeedApplied = true;
628					parent.movement.moveSpeedStat.AddMod(moveSpeedMod);
629					PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, parent.GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false));
630					SoundManager.PlayWithDistAndSPR("RunSpeed", parent.transform.position);
631				}
632				HandleAnimSpeed();
633			}
