635			public override void OnExit()
636			{
637				parent.movement.EndMovement();
638				parent.movement.moveSpeedStat.RemoveMod(moveSpeedMod);
639				parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: false);
640				parent.parryActive = false;
641			}
