643			private void HandleAnimSpeed()
644			{
645				if (!animStopwatch.IsRunning)
646				{
647					animStopwatch.IsRunning = true;
648					currentMSPercentage = parent.movement.moveSpeedStat.CurrentValue / parent.movement.moveSpeedStat.BaseValue;
649					animSpeedMod.modValue = currentMSPercentage;
650					parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: true);
651				}
652			}
653		}
